ALTER TABLE public.proposal_roles ADD COLUMN IF NOT EXISTS default_sale_rate numeric;
COMMENT ON COLUMN public.proposal_roles.default_sale_rate IS 'Explicit category sale default copied only into newly created quotes; never an HR cost or retroactive override.';
ALTER TABLE public.quote_billable_hourly_rates ADD COLUMN IF NOT EXISTS default_inherited boolean NOT NULL DEFAULT false;
CREATE OR REPLACE FUNCTION public.proposal_category_default_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF (TG_OP='INSERT' AND NEW.default_sale_rate IS NOT NULL) OR (TG_OP='UPDATE' AND NEW.default_sale_rate IS DISTINCT FROM OLD.default_sale_rate) THEN IF auth.uid() IS NOT NULL AND NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'forbidden' USING ERRCODE='42501'; END IF; IF NEW.default_sale_rate IS NOT NULL AND NEW.default_sale_rate < 0 THEN RAISE EXCEPTION 'Sale default must be nonnegative'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER proposal_category_default_guard BEFORE INSERT OR UPDATE ON public.proposal_roles FOR EACH ROW EXECUTE FUNCTION public.proposal_category_default_guard();
CREATE OR REPLACE FUNCTION public.quote_copy_category_sale_defaults() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.parent_quote_id IS NULL THEN INSERT INTO public.quote_billable_hourly_rates(quote_id,role_name,sale_rate,default_inherited) SELECT NEW.id,code,default_sale_rate,true FROM public.proposal_roles WHERE archived_at IS NULL AND default_sale_rate IS NOT NULL ON CONFLICT(quote_id,role_name) DO NOTHING; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.quote_copy_category_sale_defaults() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER quote_copy_category_sale_defaults AFTER INSERT ON public.fee_proposals FOR EACH ROW EXECUTE FUNCTION public.quote_copy_category_sale_defaults();